function openDB(){return openVault(()=>{db=null;persistenceError='Otra pestaña ha actualizado el banco. Recarga antes de guardar.';render();});}
function readDB(){return readVault(db);}
async function writeDB(value,options){revision=await writeVault(db,value,revision,options);value.revision=revision;}
let recoveryState=null, storageStatus={persistent:null,usage:null,quota:null}, unreadable=new Map();
function rebuild(){
  parsed=new Map();records=new Map();unreadable=new Map();
  for(const s of state.saves){
    try {const p=parseSave(s.bytes,s.game,s.language);parsed.set(s.id,p);p.records.forEach(pk=>{pk.key=`${s.id}/${pk.location}/${pk.box}/${pk.slot}`;pk.saveId=s.id;pk.game=s.game;pk.demo=!!s.demo;records.set(pk.key,pk);});}
    catch(e){unreadable.set(s.id,errorText(e));parsed.set(s.id,{records:[],boxes:[],trainer:'No legible con esta versión',tid:'—',checks:[{ok:false,label:'Partida en cuarentena',detail:errorText(e)}],warnings:['El original se conserva íntegro. Descárgalo o exporta el banco para recuperarlo.'],pokedex:null});}
  }
  if(!activeBox||!state.boxes.some(b=>b.id===activeBox))activeBox=state.boxes[0]?.id;
}
async function leaveDemo(){
  if(saving)throw new Error('Espera a que termine la operación.');
  const saved=db?await readDB():null;if(saved)validateState(saved);
  state=saved||fresh();revision=saved?.revision??0;demo=false;rebuild();selected.clear();transferKeys=[];
  try{sessionStorage.setItem('pv-demo-dismissed','1');}catch{}
}
async function realImportBase(){
  if(!demo)return null;
  if(!db)throw new Error('Almacenamiento no disponible.');
  const saved=await readDB();if(saved){validateState(saved);if(saved.saves.length)throw new Error('Hay un banco real. Sal de la demo antes de importar.');}
  return saved||fresh();
}
async function storageInfo(request=false){
  try {const manager=navigator.storage;if(!manager)return;
    storageStatus.persistent=request&&manager.persist?await manager.persist():manager.persisted?await manager.persisted():null;
    const estimate=await manager.estimate?.();storageStatus.usage=estimate?.usage;storageStatus.quota=estimate?.quota;
  }catch{/* Storage APIs are optional; backups remain available. */}
}
function backupReminder(){
  if(demo||!state.saves.length)return '';
  const old=!state.lastVaultExportAt||Date.now()-Date.parse(state.lastVaultExportAt)>7*86400000;
  return old||state.backupNeeded?`<div class="warning">${icon('shield')}Conserva una copia fuera del navegador: exporta tu banco .pvault. ${state.lastVaultExportAt?`Última descarga solicitada: ${date(state.lastVaultExportAt)}.`:'Todavía no has descargado un respaldo portátil.'}<button class="btn btn-light btn-small" data-nav="backups">Copias de seguridad</button></div>`:'';
}
function metaSnapshot(reason){return {id:uid(),at:new Date().toISOString(),reason,boxes:structuredClone(state.boxes),favorites:[...state.favorites],notes:{...state.notes},plans:structuredClone(state.plans)};}
let saving=false;
async function commit(reason,mutate,{snapshot=true,base=null}={}){
  if(saving)throw new Error('Hay una operación en curso. Espera un momento.');saving=true;
  try{
    const next=cloneVault(base||state);
    if(snapshot&&!base){next.snapshots.unshift(metaSnapshot(reason));next.snapshots=next.snapshots.slice(0,25);}
    await mutate(next);
    next.backups=deduplicateBackups(next.backups);
    if(!demo||base){if(!db)throw new Error('No se puede guardar en este navegador. Revisa el almacenamiento local.');await writeDB(next,{onlyEmpty:demo&&!!base});}
    state=next;if(base)demo=false;rebuild();
  }finally{saving=false;document.dispatchEvent(new Event('pokevault-idle'));}
}
function toast(message){clearTimeout(toastTimer);const t=$('#toast');t.textContent=message;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),5000);}
function errorText(e){return e?.message||'No se pudo completar la operación.';}
function saveById(id){return state.saves.find(s=>s.id===id);}
function safeName(name){return String(name).replace(/[^a-zA-Z0-9áéíóúñÁÉÍÓÚÑ_.-]/g,'_').slice(0,100)||'partida.sav';}
function stamp(){return new Date().toISOString().replace(/[:.]/g,'-').slice(0,19);}
function download(bytes,name,type='application/octet-stream'){
  const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=safeName(name);document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
}
function presentDownload(bytes,name,type='application/octet-stream',description='El archivo se ha preparado en tu navegador.'){
  const url=URL.createObjectURL(new Blob([bytes],{type}));
  showModal(`<div class="eyebrow">ARCHIVO LISTO</div><h2>Tu copia está preparada.</h2><p class="modal-sub">${esc(description)}</p><div class="info">${icon('shield')}Guárdala en tu dispositivo y comprueba la descarga antes de cerrar esta ventana.</div><div class="save-hash">${esc(name)}</div><div class="modal-actions"><button class="btn btn-light" data-close>Cerrar</button><a class="btn btn-primary" href="${url}" download="${safeName(name)}" id="ready-download">${icon('download')}Descargar archivo</a></div>`);
  const cleanup=modalCleanup;modalCleanup=()=>{cleanup?.();setTimeout(()=>URL.revokeObjectURL(url),30000);};
}
