function toBase64(b){let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));return btoa(s);}
function fromBase64(s){const t=atob(s);return Uint8Array.from(t,c=>c.charCodeAt(0));}
