function addToBank(next,keys){let box=next.boxes.find(b=>emptySlots(b)>0);for(const key of keys){if(!box||!emptySlots(box)){box={id:uid(),name:`Caja ${next.boxes.length+1}`,slots:Array(30).fill(null)};next.boxes.push(box);}box.slots[box.slots.indexOf(null)]=key;}}
async function seedDemo(){
  if(state.saves.length&&!demo)throw new Error('La demo solo se abre con un banco vacío.');
  demo=true;state=fresh();state.boxes[0].name='Compañeros';state.boxes.push({id:uid(),name:'Favoritos',slots:Array(30).fill(null)},{id:uid(),name:'Próxima aventura',slots:Array(30).fill(null)});
  const samples={firered:[6,9,3,25,94,149,143,133],crystal:[245,157,181,196,197,248,130,251],emerald:[254,257,260,282,306,330,376,384]};
  for(const [game,ids] of Object.entries(samples)){
    const bytes=game==='crystal'?makeFixtureG2(ids):makeFixtureG3(game,ids.map((s,i)=>makeDemoPK3(s,36+i*4,s*7+i)));
    state.saves.push({id:`demo-${game}`,name:`${GAMES[game].name.replaceAll(' ','_')}_DEMO.${game==='crystal'?'srm':'sav'}`,game,language:'es',bytes,hash:await sha256(bytes),at:new Date().toISOString(),demo:true});
  }
  rebuild();state.boxes[0].slots=[...records.keys(),...Array(6).fill(null)];state.favorites=[...records.keys()].filter((_,i)=>[0,3,8,20].includes(i));activeBox=state.boxes[0].id;
}
function sidebar(){const nav=[['bank','grid','Mi banco'],['saves','game','Mis partidas'],['pokedex','book','Pokédex'],['transfers','transfer','Transferencias'],['backups','shield','Copias de seguridad'],['guide','book','Guía R36S']];return `<aside class="sidebar"><a href="#bank" class="brand" aria-label="PokéVault, mi banco"><span class="brand-ball"></span><span class="brand-name">PokéVault<span class="brand-caption">TU HOME CLÁSICO</span></span></a><div class="nav-label">TU ESPACIO</div><nav class="nav">${nav.map(([id,i,label])=>`<button class="nav-button ${page===id?'active':''}" data-nav="${id}" title="${label}">${icon(i)}<span class="nav-text">${label}</span>${id==='bank'?`<span class="nav-count">${bankCount()}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="device-card"><div class="device-row">${icon('game')}<div><div class="device-title">R36S · ArkOS</div><div class="device-sub">Tu aventura de bolsillo</div></div></div><div class="device-foot"><span class="dot"></span>Instalación manual en la SD</div></div></div><div class="profile"><div class="avatar">PV</div><div><div class="profile-name">Mi banco</div><div class="profile-caption">Entrenador · espacio privado</div></div>${icon('lock','class="lock"')}</div></aside>`;}
