function demoBanner(){return demo?`<div class="demo-banner"><span>${icon('info')}Modo demo · Pokémon de ejemplo. Tus partidas todavía no están importadas.</span><button data-action="exit-demo">Salir de la demo</button></div>`:'';}
function foot(){return `<footer class="footnote"><span>${icon('lock')}Privado para ti. Guardados procesados y almacenados en este navegador.</span><span>Hecho para tus aventuras clásicas <span aria-hidden="true">✧</span> <button class="text-button" data-nav="guide">Ayuda y compatibilidad</button></span></footer>`;}
function render(){
  const titles={bank:'Mi banco',saves:'Mis partidas',pokedex:'Pokédex',transfers:'Transferencias',backups:'Copias de seguridad',guide:'Guía R36S'};
  $('#app').innerHTML=`<div class="shell">${sidebar()}<div class="main-wrap"><header class="topbar"><button class="mobile-menu" id="mobile-menu" aria-haspopup="dialog" aria-label="Abrir menú de navegación">${icon('list')}<span>Menú</span></button><div class="crumb"><span>Mi espacio</span>${icon('chevron')}<strong>${titles[page]||'Mi banco'}</strong></div><div class="topbar-right"><span class="local-label"><span class="dot"></span>${persistenceError?'Almacenamiento no disponible':demo?'Explorando la demo':'Guardado en este navegador'}</span><span class="private-chip">${icon('lock')}Solo tú</span></div></header><main class="content" id="main-content">${persistenceError?`<div class="error-box">${esc(persistenceError)}${recoveryState?'<button class="btn btn-light" id="recover-raw">Descargar recuperación sin modificar</button>':''}</div>`:''}${backupReminder()}${({bank:renderBank,saves:renderSaves,pokedex:renderPokedex,transfers:renderTransfers,backups:renderBackups,guide:renderGuide}[page]||renderBank)()}${foot()}</main></div></div>`;
  bindGlobal();
  if(page==='pokedex')bindPokedex();if(page==='bank')bindBank();if(page==='transfers')bindTransfers();if(page==='saves')bindSaves();if(page==='backups')bindBackups();
}
function navigate(next){page=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});}
function showNavigation(){
  const links=$('.sidebar .nav').innerHTML;
  showModal(`<div class="eyebrow">TU HOME CLÁSICO</div><h2 id="navigation-title">PokéVault</h2><p class="modal-sub">Todas tus aventuras, a un toque.</p><nav class="mobile-nav" aria-label="Secciones">${links}</nav>`,()=>{
    $('.modal').setAttribute('aria-labelledby','navigation-title');
    $$('.mobile-nav [data-nav]').forEach(button=>button.onclick=()=>{closeModal(false);navigate(button.dataset.nav);$('#mobile-menu')?.focus();});
  });
}
function bindGlobal(){
  $('#mobile-menu').onclick=showNavigation;
  $('#recover-raw')?.addEventListener('click',()=>presentDownload(JSON.stringify(recoveryState,(_,v)=>v instanceof Uint8Array?{type:'Uint8Array',base64:toBase64(v)}:v,null,2),'pokevault-recuperacion.json','application/json','Recuperación del estado original no compatible; conserva este archivo y no borres el almacenamiento.'));
  $$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
  $$('[data-action="import"]').forEach(b=>b.onclick=showImport);
  $$('[data-action="exit-demo"]').forEach(b=>b.onclick=async()=>{try{await leaveDemo();render();toast('Banco recuperado del almacenamiento local.');}catch(e){toast(errorText(e));}});
  $$('[data-action="demo"]').forEach(b=>b.onclick=async()=>{await seedDemo();selected.clear();render();});
}
function renderHero(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">TODAS TUS REGIONES. UN MISMO HOGAR.</div><h2>Tus aventuras,<br>en un mismo lugar.</h2><p>De Kanto a Teselia, guarda tus compañeros de siempre y prepara su próxima aventura.</p><div class="hero-foot">${icon('shield')}Tus originales, siempre a salvo.</div></div><div class="hero-art" aria-hidden="true"><div class="art-grid"></div><div class="art-circle"></div><div class="podium"></div>${img(245,'hero-pokemon main')}${img(25,'hero-pokemon left')}${img(384,'hero-pokemon right')}<span class="spark">✦</span><span class="spark two">✧</span><span class="hero-tag">TU EQUIPO. TU HISTORIA.</span></div></section>`;}
function renderStats(){const stats=[['ball',records.size,'Pokémon en tus partidas'],['game',state.saves.length,demo?'Partidas de ejemplo':'Partidas importadas'],['box',state.boxes.length,'Cajas en tu banco'],['shield','100%','Procesamiento local']];return `<div class="stats">${stats.map(([i,v,l])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><div><div class="stat-val">${v}</div><div class="stat-name">${l}</div></div></div>`).join('')}</div>`;}
function gameOptions(selectedGame){
  const labels={1:'Game Boy · generación I',2:'Game Boy Color · generación II',3:'Game Boy Advance · generación III',4:'Nintendo DS · generación IV',5:'Nintendo DS · generación V'};
  return [1,2,3,4,5].map(gen=>`<optgroup label="${labels[gen]}">${Object.entries(GAMES).filter(([,g])=>g.generation===gen).map(([key,g])=>`<option value="${key}" ${selectedGame===key?'selected':''}>Pokémon ${g.name}</option>`).join('')}</optgroup>`).join('');
}
function renderGames(){
  const imported=Object.entries(GAMES).filter(([key])=>state.saves.some(s=>s.game===key));
  const games=imported.length?imported:Object.entries(GAMES).filter(([key])=>['crystal','firered','emerald'].includes(key));
  return `<div class="section-title"><h2>Tus aventuras</h2><button class="text-button" data-nav="saves">${Object.keys(GAMES).length} juegos compatibles · Ver partidas ${icon('arrow')}</button></div><div class="games-row ${games.length>3?'many-games':''}">${games.map(([key,g])=>{const saves=state.saves.filter(s=>s.game===key);const n=saves.reduce((sum,s)=>sum+(parsed.get(s.id)?.records.length||0),0);return `<button class="game-card ${gameFilter===key?'selected':''}" data-game="${key}"><div class="game-mini ${key}">${img(g.icon)}</div><div><div class="game-name">Pokémon ${g.name}</div><div class="game-meta">${g.region} · Generación ${generationLabel(g.generation)}</div><div class="game-status"><span class="dot" style="background:${g.color}"></span>${saves.length?`${n} Pokémon · ${demo?'demo':`${saves.length} partida${saves.length>1?'s':''}`}`:'Aún sin importar'}</div></div>${icon('chevron','class="game-arrow"')}</button>`;}).join('')}</div>`;
}
function visibleKeys(){
  let keys=currentBox()?.slots.filter(Boolean)||[];
  keys=keys.filter(k=>{const p=records.get(k);if(!p)return false;return (gameFilter==='all'||p.game===gameFilter)&&(!favoriteOnly||state.favorites.includes(k))&&(!search||`${p.name} ${p.nickname} ${p.species} ${p.ot}`.toLowerCase().includes(search.toLowerCase()));});
  if(sort==='name')keys.sort((a,b)=>records.get(a).name.localeCompare(records.get(b).name));if(sort==='level')keys.sort((a,b)=>records.get(b).level-records.get(a).level);if(sort==='dex')keys.sort((a,b)=>records.get(a).species-records.get(b).species);
  return keys;
}
function card(k){const p=records.get(k);if(!p)return '';return `<div role="button" tabindex="0" class="pokemon-card ${selected.has(k)?'selected':''} ${p.valid?'':'invalid'}" data-pk="${esc(k)}" draggable="true" aria-label="${esc(p.name)}, nivel ${p.level}, ${GAMES[p.game].name}${selected.has(k)?', seleccionado':''}"><button class="card-check" data-select="${esc(k)}" aria-label="${selected.has(k)?'Deseleccionar':'Seleccionar'} ${esc(p.name)}" aria-pressed="${selected.has(k)}">${selected.has(k)?'✓':''}</button>${state.favorites.includes(k)?'<span class="star" aria-label="Favorito">✦</span>':`<span class="pk-num">#${String(p.species).padStart(3,'0')}</span>`}${img(p.species,'pokemon-img')}<div class="pokemon-name">${esc(p.name)}${p.shiny?' ✦':''}${p.egg?' · Huevo':''}</div><div class="pk-level">${p.valid?`Nv. ${p.level} ${p.location==='party'?'· Equipo':''}`:'En cuarentena'}</div><span class="card-origin" style="--game-color:${GAMES[p.game].color}"></span></div>`;}
function renderBank(){
  let body='';
  if(!records.size&&!demo){body=`<div class="empty-state"><div class="empty-illustration">${icon('box')}</div><h3>El comienzo de tu colección</h3><p>Importa una partida de Amarillo, Cristal, Rojo Fuego, Esmeralda o los juegos principales de Nintendo DS. Lo validaremos y conservaremos una copia original.</p><div class="empty-actions">${importButton('Importar mi partida')}${!state.saves.length&&!persistenceError?'<button class="btn btn-light" data-action="demo">Explorar la demo</button>':''}</div></div>`;}
  else{
    const keys=visibleKeys(),box=currentBox(),filtered=!!search||gameFilter!=='all'||favoriteOnly,empties=filtered?0:30-box.slots.filter(Boolean).length;
    body=`<section class="bank-panel ${layout==='list'?'list-view':''}"><div class="bank-top"><div><div class="bank-title"><h2>Mis cajas</h2><span class="count-chip">${bankCount()} Pokémon</span></div><p class="bank-sub">Selecciona y pulsa «Mover de caja» o arrastra · tus partidas no cambian</p></div><div class="bank-actions"><button class="btn btn-light btn-small" data-action="new-box">${icon('plus')}Nueva caja</button><button class="icon-button" data-action="rename-box" title="Renombrar caja" aria-label="Renombrar caja">${icon('edit')}</button></div></div><div class="box-tabs">${state.boxes.map(b=>`<button class="box-tab ${b.id===activeBox?'active':''}" data-box="${b.id}" data-drop-box="${b.id}">${icon('box')}${esc(b.name)} <small>${b.slots.filter(Boolean).length}</small></button>`).join('')}<button class="icon-button tab-add" data-action="new-box" title="Nueva caja" aria-label="Nueva caja">+</button></div><div class="toolbar"><div class="filters"><div class="search-wrap">${icon('search')}<input class="search-input" id="bank-search" type="search" placeholder="Buscar un Pokémon…" value="${esc(search)}" aria-label="Buscar Pokémon por nombre, mote, entrenador o número"></div><select class="select" id="game-filter" aria-label="Filtrar por juego"><option value="all">Todos los juegos</option>${Object.entries(GAMES).map(([id,g])=>`<option value="${id}" ${gameFilter===id?'selected':''}>${g.name}</option>`).join('')}</select><select class="select" id="sort-filter" aria-label="Ordenar Pokémon"><option value="slot">Orden de caja</option><option value="name" ${sort==='name'?'selected':''}>Nombre A–Z</option><option value="level" ${sort==='level'?'selected':''}>Mayor nivel</option><option value="dex" ${sort==='dex'?'selected':''}>Pokédex</option></select><button class="icon-button" id="favorites-filter" title="Solo favoritos" aria-label="Solo favoritos" aria-pressed="${favoriteOnly}" style="${favoriteOnly?'background:#f4ecd6;color:#b7994d':''}">${icon('star')}</button></div><div class="view-switch toolbar-right"><button class="${layout==='grid'?'active':''}" data-layout="grid" aria-label="Vista de cuadrícula">${icon('grid')}</button><button class="${layout==='list'?'active':''}" data-layout="list" aria-label="Vista de lista">${icon('list')}</button></div></div><div class="bank-grid">${keys.map(card).join('')}${Array.from({length:empties},(_,i)=>`<div class="pokemon-card empty" data-empty-slot="${i}" aria-hidden="true"><span class="empty-mark">+</span></div>`).join('')}${!keys.length&&filtered?'<div class="no-results">No hay resultados en esta caja.<br>Prueba otro nombre, juego o caja.</div>':''}</div><div class="bank-footer"><div class="legend">${Object.entries(GAMES).filter(([id])=>state.saves.some(s=>s.game===id)).map(([id,g])=>`<span><span class="dot" style="background:${g.color}"></span>${g.name}</span>`).join('')}</div><span>${keys.length} / 30 casillas <button data-action="select-all">Seleccionar visibles</button></span></div>${selected.size?`<div class="selection-bar"><span class="selection-count">${selected.size} seleccionado${selected.size!==1?'s':''}</span><div class="selection-actions"><button class="btn btn-light btn-small" data-action="clear-selection">Cancelar</button><button class="btn btn-light btn-small" data-action="move">${icon('folder')}Mover de caja</button><button class="btn btn-primary btn-small" data-action="plan-transfer">${icon('transfer')}Preparar transferencia</button></div></div>`:''}</section>`;
  }
  return titleBlock('Mi banco','Tus Pokémon de siempre, a buen recaudo.',importButton())+renderHero()+renderStats()+renderGames()+demoBanner()+body;
}
function bindBank(){
  $$('[data-game]').forEach(b=>b.onclick=()=>{gameFilter=gameFilter===b.dataset.game?'all':b.dataset.game;render();});
  $$('[data-box]').forEach(b=>b.onclick=()=>{activeBox=b.dataset.box;render();});
  $('#game-filter')?.addEventListener('change',e=>{gameFilter=e.target.value;render();});
  $('#sort-filter')?.addEventListener('change',e=>{sort=e.target.value;render();});
  $('#bank-search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;render();const input=$('#bank-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}});
  $('#favorites-filter')?.addEventListener('click',()=>{favoriteOnly=!favoriteOnly;render();});
  $$('[data-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.layout;render();});
  $$('[data-select]').forEach(b=>b.onclick=e=>{e.stopPropagation();const k=b.dataset.select;selected.has(k)?selected.delete(k):selected.add(k);render();});
  $$('[data-pk]').forEach(c=>{c.onclick=()=>showPokemon(c.dataset.pk);c.onkeydown=e=>{if(e.target===c&&['Enter',' '].includes(e.key)){e.preventDefault();showPokemon(c.dataset.pk);}};c.ondragstart=e=>e.dataTransfer.setData('text/pokevault',c.dataset.pk);c.ondragover=e=>e.preventDefault();c.ondrop=async e=>{e.preventDefault();const from=e.dataTransfer.getData('text/pokevault'),to=c.dataset.pk;if(!from||from===to||!records.has(from))return;try{await commit('Intercambiar casillas del banco',next=>{const a=next.boxes.find(b=>b.slots.includes(from)),z=next.boxes.find(b=>b.slots.includes(to));const ai=a.slots.indexOf(from),zi=z.slots.indexOf(to);a.slots[ai]=to;z.slots[zi]=from;});render();toast('Casillas intercambiadas. Copia de organización creada.');}catch(e){toast(errorText(e));}};});
  $$('[data-drop-box]').forEach(b=>{b.ondragover=e=>e.preventDefault();b.ondrop=async e=>{e.preventDefault();const k=e.dataTransfer.getData('text/pokevault');if(k)await moveKeys([k],b.dataset.dropBox);};});
  $$('[data-empty-slot]').forEach(c=>{c.ondragover=e=>e.preventDefault();c.ondrop=async e=>{e.preventDefault();const k=e.dataTransfer.getData('text/pokevault');if(k)await moveKeys([k],activeBox);};});
  $$('[data-action="new-box"]').forEach(b=>b.onclick=()=>showBoxEditor());
  $('[data-action="rename-box"]')?.addEventListener('click',()=>showBoxEditor(currentBox()));
  $('[data-action="select-all"]')?.addEventListener('click',()=>{visibleKeys().forEach(k=>selected.add(k));render();});
  $('[data-action="clear-selection"]')?.addEventListener('click',()=>{selected.clear();render();});
  $('[data-action="move"]')?.addEventListener('click',showMove);
  $('[data-action="plan-transfer"]')?.addEventListener('click',()=>{transferKeys=[...selected];transferPreview=null;navigate('transfers');});
}

function checksHTML(p){return `<div class="checks">${p.checks.map(c=>`<div class="check ${c.ok?'':'bad'}"><div class="check-head">${icon(c.ok?'check':'info')}${c.label}</div><div class="check-detail">${esc(c.detail)}</div></div>`).join('')}</div>`;}
function renderSaves(){return titleBlock('Mis partidas','Originales inmutables. Una copia de seguridad en cada importación.',importButton())+demoBanner()+(state.saves.length?`<div class="info">${icon('shield')}Cada archivo importado conserva su SHA-256 y sus bytes originales. La web nunca escribe directamente en tu R36S.</div><div class="save-list">${state.saves.map(s=>{const p=parsed.get(s.id);return `<article class="save-card"><div class="save-main">${img(GAMES[s.game].icon)}<div><h3>Pokémon ${GAMES[s.game].name}</h3><div class="save-filename">${esc(s.name)}</div><div class="save-meta">${esc(p.trainer)||'Entrenador'} · ID ${p.tid} · ${p.records.length} Pokémon · ${sizeLabel(s.bytes.length)} · ${date(s.at)}</div></div><span class="save-status">${icon('shield')}${demo?'Ejemplo':'Original protegido'}</span></div>${checksHTML(p)}<div class="save-hash">SHA-256 · ${s.hash}</div>${p.warnings.map(w=>`<div class="warning">${icon('info')}${esc(w)}</div>`).join('')}<div class="save-buttons"><button class="btn btn-light" data-save-download="${s.id}" ${demo?'disabled':''}>${icon('download')}Descargar original</button><button class="btn btn-soft" data-save-view="${s.id}" ${unreadable.has(s.id)?'disabled':''}>${icon('grid')}Ver Pokémon</button><button class="btn btn-light" data-save-dex="${s.id}" ${unreadable.has(s.id)?'disabled':''}>${icon('book')}Pokédex</button><button class="btn btn-light" data-save-boxes="${s.id}" ${unreadable.has(s.id)?'disabled':''}>${icon('box')}Cajas del guardado</button><button class="btn btn-danger" data-save-remove="${s.id}" ${demo?'disabled':''}>Retirar versión</button></div></article>`;}).join('')}</div>`:`<div class="empty-state"><div class="empty-illustration">${icon('game')}</div><h3>Conecta tus aventuras</h3><p>Copia desde tu SD un archivo .sav, .srm o .dsv compatible y ábrelo aquí. No se aceptan ROM, estados rápidos ni archivos comprimidos.</p>${importButton('Importar mi primera partida')}</div>`);}
async function showRemoveSave(id){
  const before=state,beforeRevision=revision;
  for(const s of [...state.saves,...state.backups])if(await sha256(s.bytes)!==s.hash){toast('Un hash no coincide. Conserva una recuperación y descarga los originales antes de retirar versiones.');return;}
  if(state!==before||revision!==beforeRevision){toast('El banco cambió. Vuelve a revisar esta versión.');return;}
  const save=saveById(id),reviewRevision=revision;if(!save)return;let downloaded=false;
  const url=URL.createObjectURL(new Blob([JSON.stringify(portableVault())],{type:'application/json'}));
  showModal(`<div class="eyebrow">RETIRAR UNA VERSIÓN ANTIGUA</div><h2>Conserva primero una copia</h2><p class="modal-sub">Se retirará ${esc(save.name)} del banco, sus Pokémon, notas y favoritos. Si ningún otro registro usa este original, se retirarán también sus respaldos locales para liberar espacio.</p><a class="btn btn-light" id="retire-download" href="${url}" download="pokevault-antes-de-retirar.pvault">Descargar banco completo</a><div class="checklist"><label><input type="checkbox" id="retire-ack">He comprobado que el .pvault se ha descargado fuera del navegador.</label></div><div class="field"><label for="retire-word">Escribe RETIRAR para confirmar</label><input id="retire-word" autocomplete="off"></div><div class="modal-actions"><button class="btn btn-light" data-close>Cancelar</button><button class="btn btn-danger" id="retire-confirm" disabled>Retirar esta versión</button></div>`,()=>{
    const update=()=>$('#retire-confirm').disabled=!downloaded||!$('#retire-ack').checked||$('#retire-word').value!=='RETIRAR';
    $('#retire-download').onclick=()=>{downloaded=true;update();};$('#retire-ack').onchange=update;$('#retire-word').oninput=update;
    $('#retire-confirm').onclick=async()=>{try{
      if(revision!==reviewRevision)throw new Error('El banco cambió desde el respaldo. Cancela y vuelve a revisarlo.');
      await commit('Retirar versión respaldada',next=>{
        next.saves=next.saves.filter(s=>s.id!==id);if(!next.saves.some(s=>s.hash===save.hash))next.backups=next.backups.filter(b=>b.hash!==save.hash);
        const keep=k=>!k?.startsWith(id+'/');
        for(const meta of [next,...next.snapshots]){meta.boxes.forEach(b=>b.slots=b.slots.map(k=>keep(k)?k:null));meta.favorites=meta.favorites.filter(keep);for(const k of Object.keys(meta.notes))if(!keep(k))delete meta.notes[k];}
        next.backupNeeded=true;
      });selected.clear();transferKeys=[];transferPreview=null;if(destinationId===id)destinationId='';closeModal();render();toast('Versión retirada. Conserva el respaldo descargado.');
    }catch(e){toast(errorText(e));}};
  });
  const cleanup=modalCleanup;modalCleanup=()=>{cleanup?.();setTimeout(()=>URL.revokeObjectURL(url),30000);};
}
function bindSaves(){
  $$('[data-save-remove]').forEach(b=>b.onclick=()=>showRemoveSave(b.dataset.saveRemove));
  $$('[data-save-dex]').forEach(b=>b.onclick=()=>{dexSaveId=b.dataset.saveDex;dexPage=0;navigate('pokedex');});
  $$('[data-save-download]').forEach(b=>b.onclick=()=>{const s=saveById(b.dataset.saveDownload);download(s.bytes,s.name);toast('Se ha iniciado la descarga del original.');});
  $$('[data-save-view]').forEach(b=>b.onclick=()=>{const s=saveById(b.dataset.saveView),first=state.boxes.find(box=>box.slots.some(k=>k&&records.get(k)?.saveId===s.id));activeBox=first?.id||activeBox;gameFilter=s.game;search='';navigate('bank');});
  $$('[data-save-boxes]').forEach(b=>b.onclick=()=>showSourceBoxes(b.dataset.saveBoxes));
}

function dexDescription(game,species){
  const entry=dexEntry(game,species,dexLanguage);
  return `<section class="dex-description"><div class="eyebrow">POKÉDEX · ${esc(GAMES[game]?.name||game)}</div>${entry?`<p lang="${entry.language}">${esc(entry.text)}</p><small>Descripción de esta edición · ${entry.language==='en'?'Inglés':'Español'} · Fuente: PokéAPI. ${entry.fallback?'La fuente no incluye el texto español de esta edición.':''}</small>`:'<p>No hay descripción documentada para esta especie en esta edición.</p>'}<small>Texto de referencia local; no se extrae del archivo de guardado.</small></section>`;
}
function renderPokedex(){
  const heading=titleBlock('Tu Pokédex','El registro de cada aventura, tal como está en el guardado.',importButton());
  if(!state.saves.length)return heading+`<div class="empty-state"><div class="empty-illustration">${icon('book')}</div><h3>Una historia por descubrir</h3><p>Importa una partida para consultar sus especies vistas y capturadas.</p>${importButton()}</div>`;
  if(!state.saves.some(s=>s.id===dexSaveId&&!unreadable.has(s.id)))dexSaveId=(state.saves.find(s=>!unreadable.has(s.id))||state.saves[0]).id;
  const save=saveById(dexSaveId),dex=parsed.get(save.id).pokedex;
  if(!dex)return heading+`<div class="warning">Esta partida no se puede leer con esta versión. Sus bytes siguen disponibles en Mis partidas y Copias de seguridad.</div><button class="btn btn-light" data-nav="saves">Mis partidas</button>`;
  const query=dexSearch.trim().toLocaleLowerCase('es');
  const species=Array.from({length:dex.maxSpecies},(_,i)=>i+1).filter(n=>(!query||String(n).includes(query)||DATA.names[n].toLocaleLowerCase('es').includes(query))&&(dexFilter==='all'||dexFilter==='caught'&&dex.caught[n-1]||dexFilter==='seen'&&dex.seen[n-1]||dexFilter==='missing'&&!dex.caught[n-1]));
  const pages=Math.max(1,Math.ceil(species.length/60));dexPage=Math.min(dexPage,pages-1);
  return heading+demoBanner()+`<div class="panel dex-controls"><div class="field"><label for="dex-save">Partida</label><select id="dex-save">${state.saves.filter(s=>!unreadable.has(s.id)).map(s=>`<option value="${s.id}" ${s.id===save.id?'selected':''}>${esc(GAMES[s.game].name+' · '+s.name)}</option>`).join('')}</select></div><div class="field"><label for="dex-search">Nombre o número nacional</label><input id="dex-search" type="search" value="${esc(dexSearch)}" placeholder="Buscar especie…"></div><div class="field"><label for="dex-filter">Mostrar</label><select id="dex-filter">${[['all','Todas'],['caught','Capturadas'],['seen','Vistas'],['missing','Sin capturar']].map(([value,label])=>`<option value="${value}" ${value===dexFilter?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="dex-language">Idioma del texto</label><select id="dex-language"><option value="es" ${dexLanguage==='es'?'selected':''}>Español (inglés si falta)</option><option value="en" ${dexLanguage==='en'?'selected':''}>English</option></select></div></div><div class="stats dex-stats">${[['book',dex.seenCount,'Especies vistas'],['ball',dex.caughtCount,'Especies capturadas'],['search',dex.maxSpecies-dex.caughtCount,'Sin registrar como capturadas']].map(([i,n,label])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><div><div class="stat-val">${n}<small> / ${dex.maxSpecies}</small></div><div class="stat-name">${label}</div></div></div>`).join('')}</div><div class="info">${icon('shield')}Consulta de solo lectura del catálogo nacional de esta generación, incluidos singulares. No es el contador regional del juego. Tener un Pokémon en las cajas no modifica sus marcas de Pokédex.</div>${dex.inconsistent?`<div class="warning">${icon('info')}${dex.inconsistent} especies están marcadas como capturadas pero no vistas en este archivo. Se muestran las marcas originales sin corregirlas.</div>`:''}<section class="panel"><div class="panel-header"><h2>Pokémon ${esc(GAMES[save.game].name)}</h2><span class="count-chip" aria-live="polite">${species.length} especies</span></div><div class="dex-grid">${species.slice(dexPage*60,(dexPage+1)*60).map(n=>`<button class="dex-card ${dex.caught[n-1]?'caught':dex.seen[n-1]?'seen':'unknown'}" data-dex-species="${n}" aria-label="${esc(DATA.names[n])}, ${dex.caught[n-1]?'capturado':dex.seen[n-1]?'visto':'sin registrar'}"><span class="dex-number">#${String(n).padStart(3,'0')}</span>${img(n)}<strong>${esc(DATA.names[n])}</strong><span class="dex-status">${dex.caught[n-1]?'✓ Capturado':dex.seen[n-1]?'◉ Visto':'— Sin registrar'}</span></button>`).join('')||'<p class="no-results">No hay especies con estos filtros.</p>'}</div><div class="dex-pagination"><button class="btn btn-light btn-small" id="dex-prev" ${dexPage===0?'disabled':''}>Anterior</button><span>Página ${dexPage+1} de ${pages}</span><button class="btn btn-light btn-small" id="dex-next" ${dexPage>=pages-1?'disabled':''}>Siguiente</button></div></section>`;
}
function bindPokedex(){
  if(!$('#dex-save'))return;
  $('#dex-save').onchange=e=>{dexSaveId=e.target.value;dexPage=0;render();};
  $('#dex-filter').onchange=e=>{dexFilter=e.target.value;dexPage=0;render();};
  $('#dex-language').onchange=e=>{dexLanguage=e.target.value;render();};
  $('#dex-search').oninput=e=>{const position=e.target.selectionStart;dexSearch=e.target.value;dexPage=0;render();const input=$('#dex-search');input.focus();try{input.setSelectionRange(position,position);}catch{}};
  $('#dex-prev').onclick=()=>{dexPage--;render();};$('#dex-next').onclick=()=>{dexPage++;render();};
  $$('[data-dex-species]').forEach(button=>button.onclick=()=>{
    const n=Number(button.dataset.dexSpecies),save=saveById(dexSaveId),dex=parsed.get(save.id).pokedex;
    showModal(`<div class="eyebrow">POKÉDEX NACIONAL · #${String(n).padStart(3,'0')}</div><h2>${esc(DATA.names[n])}</h2><p class="modal-sub">${esc(GAMES[save.game].name)} · ${esc(save.name)}</p><div class="pk-detail-hero">${img(n)}<div><h3>${dex.caught[n-1]?'Capturado':dex.seen[n-1]?'Visto':'Sin registrar'}</h3><p>Visto: ${dex.seen[n-1]?'Sí':'No'} · Capturado: ${dex.caught[n-1]?'Sí':'No'}</p></div></div>${dexDescription(save.game,n)}<p class="inline-note">Estas marcas pertenecen a la partida seleccionada. Consultar la ficha no cambia el guardado.</p><div class="modal-actions"><button class="btn btn-primary" data-close>Cerrar</button></div>`);
  });
}

function renderTransfers(){
  transferKeys=transferKeys.filter(k=>records.has(k));const picks=transferKeys.map(k=>records.get(k)),dest=saveById(destinationId);
  let result='',canExport=false;
  if(picks.length&&dest){
    try{
      const plan=prepareTransfer(dest,picks,Number(destinationBox),{date:defaultTransferDate(),customGen2To3});canExport=true;
      result=`<div class="info">${icon('check')}Ruta ${esc(plan.route)} · ${plan.placements.length} Pokémon a casillas vacías de ${esc(plan.parsed.boxes[destinationBox])}. El origen conserva sus Pokémon.</div>${plan.notes?.length?`<div class="warning">${icon('info')}<div>${plan.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div></div>`:''}`;
    }catch(e){result=`<div class="warning ${demo?'':'danger'}">${icon('info')}${esc(errorText(e))} El guardado no se modifica. Puedes conservar un plan de revisión.</div>`;}
  }
  return titleBlock('Prepara su próxima aventura','Copia dentro de tu generación o avanza por una ruta compatible.')+demoBanner()+`<div class="panel"><div class="panel-header"><div><div class="eyebrow">01 · ELIGE TUS COMPAÑEROS</div><h3>Pokémon seleccionados <span class="count-chip">${picks.length}</span></h3></div><button class="btn btn-light btn-small" data-nav="bank">${icon('grid')}Elegir desde el banco</button></div><p>Se crea un guardado nuevo con los Pokémon seleccionados en huecos libres del PC. Las conversiones muestran los cambios antes de exportar. Esta copia conserva el origen y no activa evoluciones por intercambio.</p><div class="transfer-picks">${picks.map(p=>`<div class="mini-pk">${img(p.species)}${esc(p.name)} · ${generationLabel(p.generation)}<button data-unpick="${p.key}" aria-label="Quitar ${esc(p.name)}">×</button></div>`).join('')||'<div class="transfer-empty">Selecciona Pokémon en «Mi banco» y pulsa «Preparar copia».</div>'}</div><div class="transfer-form"><div class="field"><label for="dest-save">Partida de destino</label><select id="dest-save"><option value="">Elige una partida importada</option>${state.saves.filter(s=>!unreadable.has(s.id)).map(s=>`<option value="${s.id}" ${s.id===destinationId?'selected':''}>${esc(s.name)} · ${GAMES[s.game].name} · ${date(s.at)} · ${s.hash.slice(0,8)}</option>`).join('')}</select><small>Revisa fecha y hash: utiliza la versión más reciente del guardado de tu SD.</small></div><div class="field"><label for="dest-box">Caja del guardado de destino</label><select id="dest-box" ${dest?'':'disabled'}>${(dest?parsed.get(dest.id).boxes:Array.from({length:14},(_,i)=>`Caja ${i+1}`)).map((n,i)=>{const occupied=dest?parsed.get(dest.id).records.filter(p=>p.box===i&&p.location==='pc').length:0;return `<option value="${i}" ${Number(destinationBox)===i?'selected':''}>${esc(n)} · ${occupied}/${dest&&GAMES[dest.game].generation<=2?20:30}</option>`;}).join('')}</select><small>Son las cajas reales del guardado, distintas de las del banco.</small></div></div>${dest&&GAMES[dest.game].generation===3&&picks.some(p=>p.generation===2)?`<div class="checklist custom-conversion"><label><input type="checkbox" id="custom-gen2" ${customGen2To3?'checked':''}>Permitir Cristal → GBA personalizada (no oficial). Genera PID, SID, naturaleza y habilidad; adapta DVs y entrenamiento. Revisaré los valores antes de exportar.</label></div>`:''}${result}<div class="warning">${icon('info')}Retira los objetos equipados y deposita los Pokémon en el PC antes de importar. Para avanzar de generación, olvida las MO en el juego de origen. Huevos, textos que pierden información y formas o eventos no compatibles quedan bloqueados. La integridad binaria no certifica legalidad competitiva.</div><div class="modal-actions"><button class="btn btn-light" id="save-plan" ${picks.length?'':'disabled'}>${icon('download')}Guardar plan (.json)</button><button class="btn btn-primary" id="review-transfer" ${canExport&&!demo?'':'disabled'}>${icon('shield')}Revisar y exportar ${icon('arrow')}</button></div></div><div class="panel"><h3>Rutas disponibles</h3><table class="compatibility"><thead><tr><th>Origen</th><th>Destino</th><th>Resultado</th></tr></thead><tbody><tr><td>Misma generación I, II, III, IV o V</td><td>Partida de esa generación</td><td>Copia con comprobación de compatibilidad</td></tr><tr><td>Amarillo · I</td><td>Cristal · II</td><td>Conversión de Cápsula del Tiempo</td></tr><tr><td>GBA · III</td><td>Diamante / Perla / Platino / HG / SS · IV</td><td>Conversión Parque Compi</td></tr><tr><td>DS · IV</td><td>Negro / Blanco / Negro 2 / Blanco 2 · V</td><td>Conversión Pokétransfer</td></tr><tr><td>GBA · III</td><td>DS · V</td><td>Cadena III → IV → V</td></tr><tr><td>Cristal · II</td><td>Rubí / Zafiro / Esmeralda / Rojo Fuego / Verde Hoja · III</td><td>Personalizada no oficial · activación y revisión</td></tr><tr><td>Envíos hacia atrás</td><td>—</td><td>Bloqueado</td></tr></tbody></table><p class="inline-note">El archivo se genera localmente. Estos flujos convierten datos; no ejecutan un intercambio por cable Link ni los minijuegos de transferencia.</p></div><div class="panel"><div class="eyebrow">CÓMO FUNCIONA</div><div class="step-list"><div class="step"><span class="step-num">1</span><div><h4>Revisión y conversión <span class="manual-tag auto-tag">AUTOMÁTICO</span></h4><p>Se comprueban originales, identidad, espacio y ruta. Al avanzar se adaptan los campos del Pokémon y se muestran fecha, procedencia, amistad y PP en la revisión.</p></div></div><div class="step"><span class="step-num">2</span><div><h4>Respaldo y exportación verificada <span class="manual-tag auto-tag">AUTOMÁTICO</span></h4><p>El resultado se vuelve a leer, se verifican checksums y Pokémon existentes, y se guarda un respaldo antes de preparar el ZIP con originales, resultado, hashes e instrucciones.</p></div></div><div class="step"><span class="step-num">3</span><div><h4>Instalación y comprobación <span class="manual-tag">MANUAL</span></h4><p>Cierra el emulador, conserva la copia de la SD y sigue la guía. Carga desde CONTINUAR dentro del juego. Después de verificar y guardar, importa la nueva versión para preparar la siguiente copia.</p></div></div></div></div>${state.plans.length?`<div class="panel"><h3>Historial de preparaciones</h3>${state.plans.slice().reverse().map(p=>`<div class="log-item"><div class="log-icon">${icon('transfer')}</div><div class="log-info"><strong>${p.count} Pokémon · ${esc(p.destination)}</strong><span>${date(p.at)} · ${esc(p.route||p.type)}</span></div><span class="badge">${p.type==='export'?'ZIP preparado':'Plan guardado'}</span></div>`).join('')}</div>`:''}`;
}
function bindTransfers(){
  $('#custom-gen2')?.addEventListener('change',e=>{customGen2To3=e.target.checked;transferPreview=null;render();});
  $('#dest-save').onchange=e=>{destinationId=e.target.value;destinationBox=0;transferPreview=null;render();};$('#dest-box').onchange=e=>{destinationBox=Number(e.target.value);transferPreview=null;render();};
  $$('[data-unpick]').forEach(b=>b.onclick=()=>{transferKeys=transferKeys.filter(k=>k!==b.dataset.unpick);render();});
  $('#save-plan').onclick=async()=>{try{const plan=await planManifest('manual');if(!demo)await commit('Guardar plan de transferencia',next=>{next.plans.push({id:uid(),at:plan.createdAt,count:plan.pokemon.length,destination:plan.destination?.filename||'Por decidir',type:'plan'});});jsonDownload(plan,`pokevault-plan-${stamp()}.json`);render();toast('Plan descargado. No se ha modificado ningún guardado.');}catch(e){toast(errorText(e));}};
  $('#review-transfer').onclick=reviewTransfer;
}
async function validateHashes(saves){for(const s of saves){if(s.demo)throw new SaveError('Los datos de demo no se pueden exportar como guardado jugable.');if(await sha256(s.bytes)!==s.hash)throw new SaveError('Un original cambió en memoria. Exportación bloqueada.');parseSave(s.bytes,s.game,s.language);}}
async function planManifest(mode){
  const picks=transferKeys.map(k=>records.get(k)),dest=saveById(destinationId),sources=[...new Set(picks.map(p=>p.saveId))].map(saveById);
  if(!demo)await validateHashes([...sources,...(dest?[dest]:[])]);
  return {format:'pokevault-transfer-plan',version:2,mode,demo,createdAt:new Date().toISOString(),operation:'copy-only',sources:sources.map(s=>({filename:s.name,game:s.game,sha256:s.hash})),destination:dest?{filename:dest.name,game:dest.game,sha256:dest.hash,box:Number(destinationBox)+1}:null,pokemon:picks.map(p=>({species:p.species,name:p.name,sourceFilename:saveById(p.saveId).name,sourceBox:p.location==='pc'?p.box+1:'Equipo',sourceSlot:p.slot+1,generation:p.generation,fingerprint:p.fingerprint,integrityValid:p.valid})),limitations:['El origen no se vacía: esta operación copia, no intercambia ni evoluciona.','Rutas admitidas: misma generación, I → II, III → IV, IV → V y III → IV → V. Cristal → GBA disponible como conversión personalizada con activación y revisión. Envíos hacia atrás bloqueados.','La instalación y la verificación en la R36S son manuales.','Este plan no es un archivo de guardado.']};
}
async function reviewTransfer(){
  try{
    const dest=saveById(destinationId),picks=transferKeys.map(k=>records.get(k));
    const sources=[...new Set(picks.map(p=>p.saveId))].map(saveById);await validateHashes([dest,...sources]);
    // Re-read every selected Pokémon from its immutable original, never from editable UI fields.
    for(const p of picks){const s=saveById(p.saveId),src=parseSave(s.bytes,s.game,s.language).records.find(r=>r.location===p.location&&r.box===p.box&&r.slot===p.slot);if(!src||!bytesEqual(src.raw,p.raw))throw new SaveError('El Pokémon no coincide con su guardado original.');}
    const options={date:defaultTransferDate(),customGen2To3},built=buildTransfer(dest,picks,Number(destinationBox),options);transferPreview={built,dest,sources,picks,options};
    showModal(`<div class="eyebrow">REVISIÓN FINAL · COPIA SEGURA</div><h2>Una nueva aventura, con respaldo.</h2><p class="modal-sub">Se generará un archivo nuevo para <strong>${esc(dest.name)}</strong>. Ruta ${esc(built.route)}. Los originales y la SD no se modificarán.</p><div class="status-strip"><span>${built.placements.length} Pokémon verificados</span><span>${esc(built.route)} · ${esc(built.integritySummary)}</span></div>${built.notes?.length?`<div class="warning">${icon('info')}<div>${built.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div></div>`:''}${built.placements.map(p=>`<div class="transfer-row">${img(p.pokemon.species)}<strong>${esc(p.pokemon.name)}</strong><span>${esc(built.checked.boxes[p.box])} · casilla ${p.slot+1}</span></div>`).join('')}<div class="info">${icon('shield')}El ZIP incluirá los originales de origen y destino, el guardado nuevo, un manifiesto SHA-256 y las instrucciones de instalación.</div><div class="checklist"><label><input type="checkbox" class="export-ack">He guardado dentro del juego, he cerrado el emulador y he importado las versiones más recientes.</label><label><input type="checkbox" class="export-ack">Entiendo que es una copia, conservará el origen y no activará evoluciones por intercambio. He revisado los cambios de conversión indicados.</label><label><input type="checkbox" class="export-ack">Instalaré el resultado manualmente y conservaré los originales fuera de la SD.</label></div><div id="export-error"></div><div class="modal-actions"><button class="btn btn-light" data-close>Volver</button><button class="btn btn-primary" id="export-zip" disabled>${icon('download')}Crear paquete seguro (.zip)</button></div>`,()=>{
      $$('.export-ack').forEach(c=>c.onchange=()=>$('#export-zip').disabled=!$$('.export-ack').every(x=>x.checked));$('#export-zip').onclick=exportTransfer;
    },true);
  }catch(e){toast(errorText(e));}
}
async function exportTransfer(){
  const button=$('#export-zip');button.disabled=true;button.textContent='Verificando y creando respaldo…';
  try{
    const {dest,sources,picks,options}=transferPreview;await validateHashes([dest,...sources]);
    const result=buildTransfer(dest,picks,Number(destinationBox),options);if(!bytesEqual(result.bytes,transferPreview.built.bytes))throw new SaveError('El resultado difiere del aprobado en la revisión. Vuelve a preparar la copia.');
    const resultHash=await sha256(result.bytes),manifest=await planManifest('verified-copy');manifest.route=result.route;manifest.conversionDate=options.date;manifest.conversionNotes=result.notes;manifest.customConversion=!!result.customConversion;manifest.conversions=await Promise.all(result.placements.map(async p=>({species:p.pokemon.species,fromGeneration:p.pokemon.generation,toGeneration:result.checked.generation,notes:p.conversion||[],customDetails:p.customDetails||null,sourceEntitySHA256:await sha256(p.pokemon.raw),resultEntitySHA256:await sha256(p.raw||p.pokemon.raw)})));
    manifest.result={filename:`${dest.name.replace(/\.(sav|srm|dsv)$/i,'')}.pokevault-${stamp()}.${/\.dsv$/i.test(dest.name)?'dsv':/\.srm$/i.test(dest.name)?'srm':'sav'}`,sha256:resultHash,checksumsValid:true,placements:result.placements.map(p=>({species:p.pokemon.species,box:p.box+1,slot:p.slot+1}))};
    const originals=[...new Map([dest,...sources].map(s=>[s.hash,s])).values()];
    const files=originals.map((s,i)=>({name:`originales/${i+1}-${safeName(s.name)}`,data:s.bytes}));
    files.push({name:`resultado/${safeName(manifest.result.filename)}`,data:result.bytes},{name:'manifiesto.json',data:JSON.stringify(manifest,null,2)},{name:'LEEME.txt',data:`RUTA: ${result.route}\nFECHA DE CONVERSIÓN: ${options.date}\n${(result.notes||[]).join('\n')}\n\n${INSTALL_TEXT}`});
    const zip=makeZip(files);
    await commit('Copia previa a exportación',next=>{
      for(const s of originals)next.backups.push({id:uid(),saveId:s.id,name:s.name,hash:s.hash,bytes:s.bytes.slice(),at:new Date().toISOString(),reason:'Antes de preparar transferencia'});
      next.backupNeeded=true;next.plans.push({id:uid(),at:new Date().toISOString(),count:picks.length,destination:dest.name,type:'export',resultHash,route:result.route});
    });
    closeModal();render();presentDownload(zip,`pokevault-transferencia-${stamp()}.zip`,'application/zip','Paquete verificado con originales, resultado nuevo, manifiesto SHA-256 e instrucciones. La instalación en la R36S es manual.');toast('Paquete verificado preparado con sus originales.');
  }catch(e){$('#export-error').innerHTML=`<div class="error-box">${esc(errorText(e))}</div>`;button.disabled=false;button.textContent='Reintentar exportación';}
}

function renderBackups(){return titleBlock('Cada aventura merece un respaldo','Originales, puntos de restauración y una copia portátil de tu banco.',`<button class="btn btn-primary" id="backup-all" ${demo||!state.saves.length?'disabled':''}>${icon('download')}Exportar banco</button>`)+demoBanner()+storagePanel()+`<div class="hero-mini">${icon('shield')}<div><h3>Tus originales no se tocan.</h3><p>Las copias locales viven en este navegador. Exporta tu banco para conservarlo también fuera de él.</p></div></div><div class="panel"><div class="panel-header"><div><h3>Respaldo portátil</h3><p>El archivo .pvault v2 incluye originales, respaldos, hashes, cajas, favoritos, notas, puntos de restauración e historial. Lee también respaldos v1.</p></div><button class="btn btn-light" id="restore-vault">${icon('upload')}Restaurar respaldo</button></div><p>La restauración valida todos los guardados y fusiona los que falten. Conserva tus partidas y la organización actual; no sobrescribe datos existentes.</p><input type="file" id="vault-file" accept=".pvault" hidden><div id="restore-status"></div></div><div class="panel"><div class="panel-header"><h3>Originales protegidos</h3><span class="badge">${demo?0:state.backups.length} copias</span></div>${!demo&&state.backups.length?state.backups.slice().reverse().map(b=>`<div class="log-item"><div class="log-icon">${icon('shield')}</div><div class="log-info"><strong>${esc(b.name)}</strong><span>${esc(b.reason)} · ${date(b.at)} · ${sizeLabel(b.bytes.length)}</span></div><button class="btn btn-light btn-small" data-backup-download="${b.id}">${icon('download')}Descargar</button></div>`).join(''):'<p class="backup-empty">Al importar tus partidas se creará aquí una copia de cada original.</p>'}</div><div class="panel"><div class="panel-header"><div><h3>Historial de organización</h3><p>Se conservan los últimos 25 estados anteriores a cambios en el banco.</p></div></div>${!demo&&state.snapshots.length?state.snapshots.map(s=>`<div class="log-item"><div class="log-icon">${icon('clock')}</div><div class="log-info"><strong>${esc(s.reason)}</strong><span>${date(s.at)} · ${s.boxes.length} cajas</span></div><button class="btn btn-light btn-small" data-restore-meta="${s.id}">${icon('refresh')}Restaurar</button></div>`).join(''):'<p class="backup-empty">Los cambios de cajas, favoritos y notas crearán puntos de restauración.</p>'}</div>`;}
function portableVault(){
  const blobs={};for(const item of [...state.saves,...state.backups])blobs[item.hash]??=toBase64(item.bytes);
  const strip=({bytes,demo,...metadata})=>metadata;
  return {format:'pokevault-backup',schema:2,createdAt:new Date().toISOString(),blobs,saves:state.saves.map(strip),backups:state.backups.map(strip),boxes:state.boxes,favorites:state.favorites,notes:state.notes,snapshots:state.snapshots,plans:state.plans};
}
async function exportVault(){
  const before=state,beforeRevision=revision;
  try{
    const inconsistent=[];for(const item of [...state.saves,...state.backups])if(await sha256(item.bytes)!==item.hash)inconsistent.push(item.name);
    if(state!==before||revision!==beforeRevision)throw new Error('El banco cambió mientras se preparaba el respaldo. Vuelve a exportarlo.');
    presentDownload(JSON.stringify(portableVault(),null,2),`pokevault-banco-${stamp()}.pvault`,'application/json',inconsistent.length?'Recuperación: algunos hashes no coinciden. Los bytes y hashes originales se incluyen sin corregir. Conserva este archivo; la restauración normal bloqueará las incoherencias.':'Banco completo con originales, respaldos y organización. Comprueba que se descarga fuera del navegador.');
    const at=new Date().toISOString(),exportRevision=revision;
    $('#ready-download').addEventListener('click',async()=>{try{if(revision!==exportRevision)return;await commit('Descarga de respaldo portátil',next=>{next.lastVaultExportAt=at;next.backupNeeded=!!inconsistent.length;},{snapshot:false});render();}catch(e){toast(errorText(e));}},{once:true});
  }catch(e){toast(errorText(e));}
}
function storagePanel(){
  const mb=n=>Number.isFinite(n)?`${(n/1048576).toFixed(1)} MiB`:'No disponible';
  return `<div class="panel"><h3>Almacenamiento de este navegador</h3><p>Persistencia concedida: ${storageStatus.persistent===null?'No disponible':storageStatus.persistent?'Sí':'No'}. Uso aproximado: ${mb(storageStatus.usage)} · Cuota: ${mb(storageStatus.quota)}.</p><p>El navegador decide si concede persistencia. Borrar sus datos o perder el dispositivo también borra el banco. Conserva una copia .pvault fuera del navegador.</p><button class="btn btn-light" id="request-persistence">Solicitar almacenamiento persistente</button></div>`;
}
function bindBackups(){
  $('#backup-all').onclick=exportVault;
  $('#request-persistence').onclick=async()=>{await storageInfo(true);render();};
  $('#restore-vault').onclick=()=>$('#vault-file').click();$('#vault-file').onchange=restoreVault;
  $$('[data-backup-download]').forEach(b=>b.onclick=()=>{const x=state.backups.find(x=>x.id===b.dataset.backupDownload);download(x.bytes,`respaldo-${safeName(x.name)}`);});
  $$('[data-restore-meta]').forEach(b=>b.onclick=()=>{
    const snap=state.snapshots.find(s=>s.id===b.dataset.restoreMeta);
    showModal(`<div class="eyebrow">PUNTO DE RESTAURACIÓN</div><h2>Recuperar organización</h2><p class="modal-sub">Restaurarás las cajas, favoritos y notas de ${date(snap.at)}. Se creará antes un punto del estado actual. Tus guardados originales seguirán intactos.</p><div class="modal-actions"><button class="btn btn-light" data-close>Cancelar</button><button class="btn btn-primary" id="confirm-restore">${icon('refresh')}Restaurar organización</button></div>`,()=>$('#confirm-restore').onclick=async()=>{try{await commit('Antes de restaurar organización',next=>{next.boxes=structuredClone(snap.boxes);next.favorites=[...snap.favorites];next.notes={...snap.notes};const assigned=new Set(next.boxes.flatMap(b=>b.slots).filter(Boolean));addToBank(next,[...records.keys()].filter(k=>!assigned.has(k)));});closeModal();render();toast('Organización restaurada.');}catch(e){toast(errorText(e));}});
  });
}
async function restoreVault(e){
  const f=e.target.files[0];if(!f)return;const status=$('#restore-status');status.innerHTML='<div class="info">Validando el respaldo…</div>';
  try{
    if(f.size>100*1024*1024)throw new Error('El respaldo supera el límite de 100 MiB.');
    const base=await realImportBase(),backup=await decodeBackup(JSON.parse(await f.text()),base?.saves||state.saves.filter(s=>!s.demo));
    await commit('Antes de restaurar respaldo',next=>{
      if(next.saves.length+new Set(backup.saves.filter(s=>!next.saves.some(e=>e.hash===s.hash)).map(s=>s.hash)).size>100)throw new Error('La fusión superaría 100 partidas.');
      const idMap=new Map(),now=new Date().toISOString();
      for(const s of backup.saves){let target=next.saves.find(x=>x.hash===s.hash);if(!target){target={...s,id:uid()};next.saves.push(target);next.backups.push({id:uid(),saveId:target.id,bytes:target.bytes,name:target.name,hash:target.hash,at:now,reason:'Restaurado desde respaldo portátil'});}idMap.set(s.id,target.id);}
      const mapKey=k=>k===null?null:(idMap.has(k.split('/')[0])?idMap.get(k.split('/')[0])+k.slice(k.indexOf('/')):null);
      const already=new Set(next.boxes.flatMap(b=>b.slots).filter(Boolean));
      for(const box of backup.boxes){const slots=box.slots.map(k=>{const mapped=mapKey(k);if(!mapped||already.has(mapped))return null;already.add(mapped);return mapped;});if(slots.some(Boolean)||!box.slots.some(Boolean))next.boxes.push({id:uid(),name:box.name,slots});}
      const allKeys=[];for(const s of backup.saves){try{parseSave(s.bytes,s.game,s.language).records.forEach(p=>allKeys.push(`${idMap.get(s.id)}/${p.location}/${p.box}/${p.slot}`));}catch{}}
      addToBank(next,allKeys.filter(k=>!already.has(k)));
      for(const k of backup.favorites){const mapped=mapKey(k);if(mapped&&!next.favorites.includes(mapped))next.favorites.push(mapped);}
      for(const [k,v] of Object.entries(backup.notes)){const mapped=mapKey(k);if(mapped&&!Object.hasOwn(next.notes,mapped))next.notes[mapped]=v;}
      for(const b of backup.backups)next.backups.push({...b,id:uid(),saveId:idMap.get(b.saveId)||null});
      for(const plan of backup.plans)if(!next.plans.some(p=>p.at===plan.at&&p.resultHash===plan.resultHash&&p.destination===plan.destination))next.plans.push({...plan,id:uid()});
      for(const snap of backup.snapshots){if(next.snapshots.length>=25)break;next.snapshots.push({...snap,id:uid(),boxes:snap.boxes.map(b=>({...b,id:uid(),slots:b.slots.map(mapKey)})),favorites:snap.favorites.map(mapKey).filter(Boolean),notes:Object.fromEntries(Object.entries(snap.notes).map(([k,v])=>[mapKey(k),v]).filter(([k])=>k)),plans:structuredClone(snap.plans)});}
      next.backupNeeded=true;
    },{base,snapshot:!!(base||state).saves.length});selected.clear();transferKeys=[];render();toast('Respaldo validado y fusionado. Se han conservado tus datos anteriores.');storageInfo(true).then(()=>render());
  }catch(error){status.innerHTML=`<div class="error-box">${esc(errorText(error))} No se ha cambiado el banco.</div>`;}
}

const INSTALL_TEXT=`POKÉVAULT · INSTALACIÓN MANUAL EN R36S / ARKOS\n\nEste paquete contiene copias de batería. No son estados rápidos ni ROM.\n\n1. Guarda dentro del menú del juego, cierra el juego y apaga la R36S correctamente.\n2. Copia el guardado actual de la SD a tu ordenador antes de instalar nada. Guarda también la carpeta originales de este ZIP fuera de la SD.\n3. Localiza el guardado de batería utilizado por tu emulador. En DS usa la batería del emulador, no un estado rápido .dss. En ArkOS suele estar junto a la ROM en /roms/gba o /roms/gbc; con segunda SD puede ser /roms2. La configuración puede cambiar la ruta.\n4. Compara el SHA-256 del guardado de la SD con el hash de destino de manifiesto.json. Si no coincide, importa la versión actual y vuelve a preparar la copia.\n   Windows PowerShell: Get-FileHash -Algorithm SHA256 -LiteralPath 'RUTA_DE_TU_GUARDADO'\n   Linux: sha256sum -- 'RUTA_DE_TU_GUARDADO'\n5. Conserva el original con un nombre de respaldo. Copia SOLO el archivo de resultado y dale el nombre y la extensión exactos que espera el emulador (.srm, .sav o .dsv, conservando el formato original). Un .dsv con pie no se convierte a .sav cambiando la extensión. Si no sabes qué ruta usa, revisa RetroArch > Ajustes > Directorio > Archivos de guardado. No adivines.\n6. Inicia la ROM normalmente y elige CONTINUAR dentro del juego. Evita cargar un estado rápido antiguo o una reanudación automática.\n7. Comprueba el entrenador, equipo y las casillas indicadas; después guarda dentro del juego, cierra y vuelve a abrir.\n8. Si aparece cualquier problema, cierra el emulador y restaura la copia original de la SD.\n\nLos Pokémon se COPIAN: permanecen en la partida de origen y no evolucionan por intercambio. No se modifican banderas de Pokédex ni progreso. La integridad binaria no certifica legalidad competitiva.\nRutas disponibles: misma generación I/II/III/IV/V, I a II, III a IV, IV a V y cadena III a IV a V. Cristal II → GBA III solo está disponible en modo personalizado no oficial, con activación y revisión. Los envíos hacia atrás y II → IV/V directos están bloqueados. No se ejecutan minijuegos de transferencia ni se emula un cable Link. Tras comprobar y guardar el resultado, vuelve a importarlo para preparar la siguiente copia.\n`;
function renderGuide(){
 return titleBlock('De tu SD a tu banco. Y de vuelta.','Copias, conversiones y pasos manuales con los originales protegidos.')+`<div class="panel"><div class="eyebrow">COMPATIBILIDAD</div><h3>Importación y exportación de copias</h3><table class="compatibility"><thead><tr><th>Juego</th><th>Importar</th><th>Exportar copia</th><th>Cajas PC</th></tr></thead><tbody>${Object.entries(GAMES).sort(([,a],[,b])=>a.generation-b.generation).map(([key,g])=>`<tr><td>${esc(g.name)} · ${generationLabel(g.generation)}</td><td>✓ · ${g.generation>=4?'512':g.generation===3?'128':'32'} KiB</td><td>✓ · con validación</td><td>${g.generation===1?12:g.generation===2||g.generation===3?14:g.generation===4?18:24}</td></tr>`).join('')}</tbody></table><div class="warning">${icon('info')}Juegos originales compatibles. Amarillo y Cristal requieren batería internacional de 32 KiB; GBA, 128 KiB; DS, 512 KiB o .dsv de 524328 / 524410 bytes con pie DeSmuME válido. ROM hacks, estados rápidos y guardados comprimidos no son compatibles. El archivo original se conserva completo.</div><p>La copia se genera como archivo nuevo. La web no accede a tu SD, no borra Pokémon del origen ni activa evoluciones por intercambio. No modifica la Pokédex, la bolsa ni el progreso de la aventura.</p></div><div class="panel"><h3>Qué puede viajar a cada generación</h3><table class="compatibility"><thead><tr><th>Ruta</th><th>Operación</th></tr></thead><tbody><tr><td>I → I · II → II · III → III · IV → IV · V → V</td><td>Copia a una partida de la misma generación</td></tr><tr><td>Amarillo → Cristal · I → II</td><td>Conversión de Cápsula del Tiempo</td></tr><tr><td>GBA → DS IV · III → IV</td><td>Conversión Parque Compi</td></tr><tr><td>DS IV → DS V · IV → V</td><td>Conversión Pokétransfer</td></tr><tr><td>GBA → DS V · III → IV → V</td><td>Cadena de ambas conversiones</td></tr><tr><td>Cristal → GBA</td><td>Personalizada no oficial, con revisión de datos generados</td></tr><tr><td>Envíos hacia atrás</td><td>Bloqueado</td></tr></tbody></table><p>En las rutas convencionales se conservan identidad, experiencia, DVs o IVs, EVs y movimientos compatibles. Cristal → GBA es una política personalizada: genera identidad GBA y adapta DVs y entrenamiento, con revisión explícita. La procedencia, fecha, amistad y PP se adaptan al formato de destino y se detallan antes de exportar. I → II convierte la tasa de captura en objeto según la Cápsula del Tiempo. Las demás copias requieren retirar los objetos equipados en origen.</p><div class="warning">${icon('info')}Se bloquean huevos, equipo fuera del PC, MO al avanzar de generación, textos con pérdida de información y ciertas formas o eventos especiales. Corrige el caso dentro del juego, guarda y vuelve a importar. Los Pokémon de exportación deben ser de idiomas internacionales compatibles. En Game Boy se requiere el mismo grupo de idioma de origen y destino.</div><p>La validación de integridad no equivale a un análisis completo de legalidad competitiva. El flujo convierte datos localmente; no ejecuta los minijuegos de transferencia ni emula un cable Link.</p></div><div class="panel"><h3>Tu recorrido seguro</h3><div class="step-list"><div class="step"><span class="step-num">1</span><div><h4>Prepara las partidas <span class="manual-tag">MANUAL · R36S</span></h4><p>Deposita los Pokémon en el PC, retira sus objetos y, si vas a avanzar de generación, olvida las MO que indique la web. Guarda desde el menú de Pokémon, cierra el emulador y apaga ArkOS correctamente antes de extraer la SD.</p></div></div><div class="step"><span class="step-num">2</span><div><h4>Copia e importa los guardados más recientes <span class="manual-tag">MANUAL · ORDENADOR</span></h4><p>Conserva una copia externa. En ArkOS los guardados suelen estar junto a la ROM, por ejemplo <span class="code">/roms/gba/</span> o <span class="code">/roms/gbc/</span>, según configuración y SD. En RetroArch revisa Ajustes → Directorio → Archivos de guardado. En DraStic usa la batería .dsv, no el estado rápido .dss.</p></div></div><div class="step"><span class="step-num">3</span><div><h4>Elige origen, partida y caja de destino <span class="manual-tag auto-tag">WEB · VALIDACIÓN</span></h4><p>Desde «Mi banco», selecciona los Pokémon y prepara la copia. Comprueba la fecha y el hash de la partida elegida. Las cajas del banco son organización local; el destino se elige entre las cajas reales del guardado. En Amarillo sin bancos inicializados solo se usa su caja activa.</p></div></div><div class="step"><span class="step-num">4</span><div><h4>Revisa los cambios de conversión <span class="manual-tag auto-tag">WEB · REVISIÓN</span></h4><p>La revisión muestra ruta, cambios de datos y fecha. Antes de preparar el paquete se vuelve a leer el resultado, se verifican los Pokémon y checksums, y se comprueba que los Pokémon anteriores sigan intactos. Se bloquean casillas ocupadas y duplicados, incluso después de convertir.</p></div></div><div class="step"><span class="step-num">5</span><div><h4>Descarga el ZIP y comprueba el hash de la SD <span class="manual-tag">MANUAL · ORDENADOR</span></h4><p>El paquete incluye originales, resultado, hashes y registro de conversiones. El SHA-256 del destino en la SD debe coincidir con el del manifiesto. Si cambió, importa esa nueva versión y prepara la copia otra vez. En PowerShell: <span class="code">Get-FileHash -Algorithm SHA256 -LiteralPath 'ruta'</span>. En Linux: <span class="code">sha256sum -- 'ruta'</span>.</p></div></div><div class="step"><span class="step-num">6</span><div><h4>Instala y comprueba el resultado <span class="manual-tag">MANUAL · R36S</span></h4><p>Con el emulador cerrado, conserva el guardado anterior y copia el resultado con el nombre exacto que espera el emulador. Respeta el formato: un .dsv con pie no se convierte a .sav cambiando la extensión. Abre desde CONTINUAR dentro del juego, evitando estados rápidos o reanudación automática. Revisa las cajas, guarda, cierra y vuelve a abrir. Si falla, restaura el original.</p></div></div><div class="step"><span class="step-num">7</span><div><h4>Importa el resultado para continuar <span class="manual-tag">MANUAL · WEB</span></h4><p>Cuando hayas comprobado la nueva partida, vuelve a importarla para que el banco refleje ese archivo y la siguiente transferencia parta de su versión actual. Los originales anteriores permanecen protegidos.</p></div></div></div><button class="btn btn-light" id="download-guide">${icon('download')}Descargar instrucciones</button></div><div class="panel"><h3>Alcance de la lectura</h3><p>Se leen cajas de PC, equipo y marcas de Pokédex. No se extraen guardería, GTS, Pokéwalker, caja de combate ni otros contenidos auxiliares. En DS IV se comprueban bloques generales y PC; en DS V, bloques principales y espejos CRC. La exportación conserva los datos auxiliares y el pie DSV original. Los datos en cuarentena necesitan revisión antes de usar esa partida como destino.</p></div><div class="panel"><h3>Privacidad y conservación</h3><p>El acceso al sitio es privado. Guardados, respaldos y notas se procesan en tu dispositivo y se conservan en este navegador. No hay subida de partidas, analítica ni sincronización entre equipos. Borrar los datos del navegador elimina el banco local: exporta periódicamente el respaldo .pvault.</p><div class="sources">Fuentes técnicas y créditos: <a href="https://github.com/kwsch/PKHeX/blob/master/PKHeX.Core/PKM/PK3.cs" target="_blank" rel="noopener noreferrer">Conversión III → IV</a><a href="https://github.com/kwsch/PKHeX/blob/master/PKHeX.Core/PKM/PK4.cs" target="_blank" rel="noopener noreferrer">Conversión IV → V</a><a href="https://github.com/pret/pokeyellow/blob/master/engine/menus/save.asm" target="_blank" rel="noopener noreferrer">Guardado Amarillo</a><a href="https://github.com/pret/pokecrystal" target="_blank" rel="noopener noreferrer">Cristal</a><a href="https://github.com/kwsch/PKHeX" target="_blank" rel="noopener noreferrer">PKHeX · GPL-3.0</a><a href="https://github.com/PokeAPI/sprites" target="_blank" rel="noopener noreferrer">Sprites · PokéAPI</a><a href="./LICENSE" target="_blank" rel="noopener">Licencia</a><br>Proyecto personal no oficial. Pokémon pertenece a Nintendo, Game Freak y The Pokémon Company.</div></div>`;
}

function showModal(html,bind=()=>{},wide=false){
  closeModal(false);lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="PokéVault"><button class="icon-button modal-close" data-close aria-label="Cerrar">${icon('close')}</button>${html}</section></div>`;document.body.classList.add('modal-open');$('#app').inert=true;$$('[data-close]',$('#modal-root')).forEach(b=>b.onclick=()=>closeModal());
  $('.modal-overlay').onmousedown=e=>{if(e.target===$('.modal-overlay'))closeModal();};
  const keydown=e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=$$('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]',$('.modal')).filter(el=>el.offsetParent!==null);const a=items[0],z=items.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();z?.focus();}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a?.focus();}}};document.addEventListener('keydown',keydown);modalCleanup=()=>document.removeEventListener('keydown',keydown);bind();$('.modal-close')?.focus();
}
function closeModal(focus=true){modalCleanup?.();modalCleanup=null;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');$('#app').inert=false;document.dispatchEvent(new Event('pokevault-idle'));if(focus){if(lastFocus?.isConnected)lastFocus.focus();else $('#mobile-menu')?.focus();}}
function showBoxEditor(box=null){showModal(`<div class="eyebrow">ORGANIZACIÓN DEL BANCO</div><h2>${box?'Un nombre para esta caja':'Más espacio para tu equipo'}</h2><p class="modal-sub">Cada caja tiene 30 casillas. La organización es local y no altera las cajas de los guardados.</p><div class="field"><label for="box-name">Nombre de la caja</label><input id="box-name" maxlength="30" value="${esc(box?.name||`Caja ${state.boxes.length+1}`)}" autocomplete="off"></div><div class="modal-actions"><button class="btn btn-light" data-close>Cancelar</button><button class="btn btn-primary" id="box-save">${icon(box?'check':'plus')}${box?'Guardar nombre':'Crear caja'}</button></div>`,()=>{$('#box-save').onclick=async()=>{const name=$('#box-name').value.trim();if(!name)return toast('Escribe un nombre para la caja.');try{await commit(box?'Renombrar caja':'Crear caja',next=>{if(box)next.boxes.find(b=>b.id===box.id).name=name;else{const b={id:uid(),name,slots:Array(30).fill(null)};next.boxes.push(b);activeBox=b.id;}});closeModal();render();toast(demo?'Caja de demo actualizada.':'Caja guardada con punto de restauración.');}catch(e){toast(errorText(e));}};$('#box-name').onkeydown=e=>{if(e.key==='Enter')$('#box-save').click();};});}
async function moveKeys(keys,to){
  keys=keys.filter(k=>records.has(k)&&!state.boxes.find(b=>b.id===to)?.slots.includes(k));if(!keys.length)return;
  try{const target=state.boxes.find(b=>b.id===to);if(!target||emptySlots(target)<keys.length)throw new Error('La caja no tiene suficientes casillas libres.');await commit('Mover Pokémon entre cajas del banco',next=>{for(const b of next.boxes)b.slots=b.slots.map(k=>keys.includes(k)?null:k);const b=next.boxes.find(x=>x.id===to);for(const k of keys)b.slots[b.slots.indexOf(null)]=k;});selected.clear();closeModal();render();toast(`${keys.length} Pokémon movido${keys.length===1?'':'s'}. Los guardados originales no cambian.`);}catch(e){toast(errorText(e));}
}
function showMove(){showModal(`<div class="eyebrow">CAJAS DEL BANCO</div><h2>Un nuevo lugar para tus compañeros</h2><p class="modal-sub">Moverás ${selected.size} Pokémon dentro del banco. Tus partidas seguirán intactas.</p><div class="field"><label for="move-target">Caja de destino</label><select id="move-target">${state.boxes.map(b=>`<option value="${b.id}">${esc(b.name)} · ${emptySlots(b)} huecos</option>`).join('')}</select></div><div class="modal-actions"><button class="btn btn-light" data-close>Cancelar</button><button class="btn btn-primary" id="move-confirm">${icon('folder')}Mover Pokémon</button></div>`,()=>$('#move-confirm').onclick=()=>moveKeys([...selected],$('#move-target').value));}
function showPokemon(key){
  const p=records.get(key);if(!p)return;const s=saveById(p.saveId),fav=state.favorites.includes(key);
  showModal(`<div class="eyebrow">FICHA DEL POKÉMON · #${String(p.species).padStart(3,'0')}</div><h2>${esc(p.nickname||p.name)}${p.shiny?' ✦':''}</h2><p class="modal-sub">${esc(p.name)} · Pokémon ${GAMES[p.game].name} ${demo?'· Datos de ejemplo':''}</p><div class="pk-detail-hero">${img(p.species)}<div><h3>Nv. ${p.level}</h3><p>${p.egg?'Huevo':p.shiny?'Variocolor':'Tu compañero de aventura'}${p.form?` · Forma ID ${p.form}`:''}</p><div class="type-pills">${p.types.map(t=>`<span class="type-pill">${TYPE_NAMES[t]}</span>`).join('')}</div></div></div>${dexDescription(p.game,p.species)}<div class="detail-grid"><div class="detail-field"><small>Entrenador original</small><span>${esc(p.ot)||'Sin nombre'} · ${p.tid}</span></div><div class="detail-field"><small>Ubicación en el original</small><span>${esc(p.boxName)} · casilla ${p.slot+1}</span></div><div class="detail-field"><small>Integridad de estructura</small><span>${p.valid?'✓ Verificada':'⚠ En cuarentena'}${p.generation<=2?' · sin checksum individual':''}</span></div><div class="detail-field"><small>Objeto equipado</small><span>${p.heldItem?`ID ${p.heldItem} · Gen. ${p.generation}`:'Sin objeto'}</span></div></div><div class="field-label">Movimientos</div><div class="move-list">${p.moves.map(m=>`<div class="move">${m?esc(DATA.moves[m]||`Movimiento ${m}`):'—'}</div>`).join('')}</div><div class="field"><label for="pk-note">Nota personal</label><textarea id="pk-note" maxlength="1000" placeholder="Una aventura, un recuerdo…">${esc(state.notes[key]||'')}</textarea><small>Solo cambia tu nota en el banco.</small></div>${!p.valid?'<div class="error-box">Este Pokémon no se puede transferir. Conserva el original y revisa la partida.</div>':''}<div class="modal-actions"><button class="btn btn-light" id="pk-favorite">${icon('star')}${fav?'Quitar favorito':'Favorito'}</button><button class="btn btn-light" id="pk-note-save">Guardar nota</button><button class="btn btn-primary" id="pk-transfer" ${p.valid?'':'disabled'}>${icon('transfer')}Preparar copia</button></div>`,()=>{
    $('#pk-favorite').onclick=async()=>{try{await commit(fav?'Quitar favorito':'Añadir favorito',next=>{next.favorites=fav?next.favorites.filter(k=>k!==key):[...next.favorites,key];});render();showPokemon(key);toast('Favoritos actualizados.');}catch(e){toast(errorText(e));}};
    $('#pk-note-save').onclick=async()=>{const note=$('#pk-note').value;try{await commit('Actualizar nota personal',next=>{next.notes[key]=note;});closeModal();render();toast('Nota guardada.');}catch(e){toast(errorText(e));}};
    $('#pk-transfer').onclick=()=>{transferKeys=[key];transferPreview=null;closeModal();navigate('transfers');};
  });
}
function showSourceBoxes(id){
  const s=saveById(id),p=parsed.get(id);let box=0;
  const draw=()=>{showModal(`<div class="eyebrow">GUARDADO ORIGINAL · SOLO LECTURA</div><h2>Pokémon ${GAMES[s.game].name}</h2><p class="modal-sub">${esc(s.name)} · Estas son las ubicaciones reales del guardado. Mover en el banco no las modifica.</p><div class="field"><label for="source-box">Caja del guardado</label><select id="source-box">${p.boxes.map((n,i)=>`<option value="${i}" ${box===i?'selected':''}>${esc(n)} · ${p.records.filter(r=>r.box===i).length}/${p.boxCapacity||(p.generation<=2?20:30)}</option>`).join('')}<option value="-1" ${box===-1?'selected':''}>Equipo</option></select></div><div class="bank-grid source-box-grid">${p.records.filter(r=>r.box===box).map(r=>card(r.key)).join('')||'<p class="no-results">Esta caja está vacía.</p>'}</div>`,()=>{$('#source-box').onchange=e=>{box=Number(e.target.value);draw();};$$('[data-pk]',$('.modal')).forEach(c=>{c.onclick=()=>showPokemon(c.dataset.pk);c.onkeydown=e=>{if(e.key==='Enter')showPokemon(c.dataset.pk);};});$$('[data-select]',$('.modal')).forEach(b=>b.onclick=e=>{e.stopPropagation();showPokemon(b.dataset.select);});},true);};draw();
}

function showImport(){
  let pending=null,busy=false,readToken=0;
  showModal(`<div class="eyebrow">UNA NUEVA AVENTURA EN TU BANCO</div><h2>Importa tu guardado</h2><p class="modal-sub">Abre una copia del archivo de batería de tu R36S. El original se conservará íntegro y no saldrá de este navegador.</p><div class="transfer-form"><div class="field"><label for="import-game">Juego del guardado</label><select id="import-game">${gameOptions('emerald')}</select></div><div class="field"><label for="import-language">Idioma (Amarillo / Cristal)</label><select id="import-language"><option value="es">Español</option><option value="en">Inglés</option><option value="fr">Francés</option><option value="it">Italiano</option><option value="de">Alemán</option></select><small>Elige el idioma exacto de Game Boy para convertir; GBA y DS leen el de cada Pokémon.</small></div></div><label class="dropzone" id="dropzone" for="save-file">${icon('upload')}<strong>Tu próxima aventura empieza aquí</strong><span>Toca para elegir un archivo de tu dispositivo o arrástralo aquí</span><small id="import-requirements">${saveRequirements('emerald')}</small><input id="save-file" type="file" accept=".sav,.srm,.dsv"></label><div id="import-status"></div><div class="warning">${icon('shield')}Juegos originales: Amarillo y Cristal internacionales, GBA y Pokémon principales de Nintendo DS. Se rechazan estados rápidos, ROM hacks y formatos no compatibles. No se modifica el archivo seleccionado.</div><div class="modal-actions"><button class="btn btn-light" data-close>Cancelar</button><button class="btn btn-primary" id="import-confirm" disabled>${icon('shield')}Importar y crear respaldo</button></div>`,()=>{
    const fileInput=$('#save-file'),game=$('#import-game'),lang=$('#import-language'),status=$('#import-status'),confirm=$('#import-confirm');
    let chosenFile=null;
    const inspect=async file=>{
      const token=++readToken;pending=null;confirm.disabled=true;if(!file)return;
      chosenFile=file;status.innerHTML='<div class="info">Comprobando tamaño, estructura y SHA-256…</div>';
      try{
        if(!/\.(sav|srm|dsv)$/i.test(file.name))throw new SaveError('Elige un archivo de batería .sav, .srm o .dsv compatible.');
        if(!validFileSize(file.size,game.value))throw new SaveError(`Tamaño no compatible: ${file.size} bytes. ${GAMES[game.value].name} requiere ${saveRequirements(game.value)}. El archivo original no se alterará.`);
        const bytes=new Uint8Array(await file.arrayBuffer()),result=parseSave(bytes,game.value,lang.value),hash=await sha256(bytes);
        if(token!==readToken)return;
        if(!demo&&state.saves.some(s=>s.hash===hash))throw new SaveError('Este guardado exacto ya está en tu banco. No se ha importado otra copia.');
        if(!demo&&state.saves.length>=100)throw new SaveError('El banco admite hasta 100 guardados. Exporta tu respaldo antes de continuar.');
        pending={id:uid(),name:file.name,game:game.value,language:lang.value,bytes,hash,at:new Date().toISOString()};
        status.innerHTML=`<div class="import-summary">${img(GAMES[game.value].icon)}<div><h3>${esc(file.name)}</h3><p>${esc(result.trainer)} · ${result.records.length} Pokémon · ${sizeLabel(bytes.length)}</p></div></div>${checksHTML(result)}<div class="save-hash">SHA-256 · ${hash}</div>${result.warnings.map(w=>`<div class="warning">${icon('info')}${esc(w)}</div>`).join('')}${demo?'<div class="info">La demo se cerrará al importar. Tus Pokémon se guardarán en un banco nuevo.</div>':''}`;confirm.disabled=false;
      }catch(e){if(token!==readToken)return;status.innerHTML=`<div class="error-box">${esc(errorText(e))} El banco sigue intacto.</div>`;}
    };
    fileInput.onchange=()=>inspect(fileInput.files[0]);game.onchange=()=>{$('#import-requirements').textContent=saveRequirements(game.value);inspect(chosenFile);};lang.onchange=()=>inspect(chosenFile);
    const zone=$('#dropzone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover');};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');if(e.dataTransfer.files.length!==1){status.innerHTML='<div class="error-box">Importa un solo guardado cada vez.</div>';return;}inspect(e.dataTransfer.files[0]);};
    confirm.onclick=async()=>{
      if(!pending||busy)return;busy=true;confirm.disabled=true;game.disabled=true;lang.disabled=true;fileInput.disabled=true;
      try{
        const item=pending;if(await sha256(item.bytes)!==item.hash)throw new Error('El archivo cambió después de validarlo.');parseSave(item.bytes,item.game,item.language);
        await commit('Antes de importar partida',next=>{if(next.saves.some(s=>s.hash===item.hash))throw new Error('Este original ya existe.');if(next.saves.length>=100)throw new Error('Límite de 100 partidas.');next.backupNeeded=true;next.saves.push(item);next.backups.push({id:uid(),saveId:item.id,name:item.name,bytes:item.bytes.slice(),hash:item.hash,at:item.at,reason:'Original al importar'});const p=parseSave(item.bytes,item.game,item.language);addToBank(next,p.records.map(r=>`${item.id}/${r.location}/${r.box}/${r.slot}`));},{base:await realImportBase()});
        activeBox=state.boxes.find(b=>b.slots.some(k=>k?.startsWith(item.id+'/')))?.id||state.boxes[0].id;selected.clear();transferKeys=[];gameFilter='all';search='';favoriteOnly=false;closeModal();navigate('bank');toast('Partida validada e importada. Exporta tu respaldo portátil.');storageInfo(true).then(()=>render());
      }catch(e){status.innerHTML+=`<div class="error-box">${esc(errorText(e))} No se ha importado la partida.</div>`;busy=false;confirm.disabled=false;game.disabled=false;lang.disabled=false;fileInput.disabled=false;}
    };
  },true);
}

document.addEventListener('click',e=>{if(e.target.closest('#download-guide'))download(INSTALL_TEXT,'pokevault-guia-r36s.txt','text/plain;charset=utf-8');});
async function init(){
  try{
    db=await openDB();recoveryState=await dumpVault(db);const saved=await readDB();
    if(saved){validateState(saved);if(saved.saves.some(s=>!GAMES[s.game]))throw new Error('Juego desconocido en el banco.');state=saved;revision=saved.revision??0;rebuild();}
    recoveryState=null;
  }catch(e){persistenceError=`${errorText(e)} No se sobrescribirá el banco. Conserva una recuperación antes de cambiar de versión.`;db?.close();db=null;state=fresh();}
  if(!state.saves.length&&!persistenceError){let dismissed=false;try{dismissed=sessionStorage.getItem('pv-demo-dismissed')==='1';}catch{}if(!dismissed)await seedDemo();else rebuild();}
  await storageInfo();
  if(['bank','saves','pokedex','transfers','backups','guide'].includes(location.hash.slice(1)))page=location.hash.slice(1);
  window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['bank','saves','pokedex','transfers','backups','guide'].includes(p)&&p!==page){page=p;render();}});
  render();
}
document.addEventListener('pokevault-navigation-check',e=>{if(saving||$('#modal-root').children.length)e.preventDefault();});
init().catch(e=>{$('#app').innerHTML=`<div class="empty-state"><h2>No se pudo abrir el banco</h2><p>${esc(errorText(e))}</p><button class="btn btn-light" id="retry-init">Recargar</button></div>`;$('#retry-init').addEventListener('click',()=>location.reload());});
